package com.tekwatt.billing.entity;import jakarta.persistence.*;import java.math.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="bills")public class Bill{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false)private UUID userId;@Column(nullable=false,unique=true)private UUID sessionId;private UUID tariffId;@Column(nullable=false,unique=true,length=50)private String billNumber;@Column(nullable=false,precision=12,scale=3)private BigDecimal energyKwh;@Column(nullable=false)private Long durationMinutes;@Column(nullable=false,precision=12,scale=2)private BigDecimal energyAmount;@Column(nullable=false,precision=12,scale=2)private BigDecimal timeAmount;@Column(nullable=false,precision=12,scale=2)private BigDecimal sessionFee;@Column(nullable=false,precision=12,scale=2)private BigDecimal subtotal;@Column(nullable=false,precision=5,scale=2)private BigDecimal taxPercent;@Column(nullable=false,precision=12,scale=2)private BigDecimal taxAmount;@Column(nullable=false,precision=12,scale=2)private BigDecimal totalAmount;@Column(nullable=false,length=3)private String currency;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private BillStatus status;@Column(nullable=false,updatable=false)private Instant createdAt;private Instant paidAt;@Column(nullable=false)private Instant updatedAt;protected Bill(){}public Bill(UUID t,UUID u,UUID s,UUID tariff,String num,BigDecimal energy,long minutes,BigDecimal energyRate,BigDecimal timeRate,BigDecimal fee,BigDecimal tax,String cur){id=UUID.randomUUID();tenantId=t;userId=u;sessionId=s;tariffId=tariff;billNumber=num;energyKwh=energy;durationMinutes=minutes;energyAmount=energy.multiply(energyRate).setScale(2,RoundingMode.HALF_UP);timeAmount=timeRate.multiply(BigDecimal.valueOf(minutes)).setScale(2,RoundingMode.HALF_UP);sessionFee=fee;subtotal=energyAmount.add(timeAmount).add(fee).setScale(2,RoundingMode.HALF_UP);taxPercent=tax;taxAmount=subtotal.multiply(tax).divide(BigDecimal.valueOf(100),2,RoundingMode.HALF_UP);totalAmount=subtotal.add(taxAmount);currency=cur.toUpperCase();status=BillStatus.PENDING;createdAt=Instant.now();updatedAt=createdAt;}public void pay(){status=BillStatus.PAID;paidAt=Instant.now();updatedAt=paidAt;}public void voidBill(){status=BillStatus.VOID;updatedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getUserId(){return userId;}public UUID getSessionId(){return sessionId;}public UUID getTariffId(){return tariffId;}public String getBillNumber(){return billNumber;}public BigDecimal getEnergyKwh(){return energyKwh;}public Long getDurationMinutes(){return durationMinutes;}public BigDecimal getEnergyAmount(){return energyAmount;}public BigDecimal getTimeAmount(){return timeAmount;}public BigDecimal getSessionFee(){return sessionFee;}public BigDecimal getSubtotal(){return subtotal;}public BigDecimal getTaxPercent(){return taxPercent;}public BigDecimal getTaxAmount(){return taxAmount;}public BigDecimal getTotalAmount(){return totalAmount;}public String getCurrency(){return currency;}public BillStatus getStatus(){return status;}public Instant getCreatedAt(){return createdAt;}public Instant getPaidAt(){return paidAt;}public Instant getUpdatedAt(){return updatedAt;}}
